from hypothesis import strategies as st


def _parse(inp):
    t = inp.split()
    pos = 0
    n = int(t[pos]); pos += 1
    pre = [None] * (n + 1)
    for i in range(1, n + 1):
        c = int(t[pos]); pos += 1
        ps = [int(x) for x in t[pos:pos + c]]
        pos += c
        pre[i] = ps
    if pos != len(t):
        raise ValueError("trailing tokens")
    return n, pre


@st.composite
def gen(draw):
    n = draw(st.integers(2, 6))
    perm = draw(st.permutations(list(range(1, n + 1))))
    perm = list(perm)
    if perm[0] == 1:
        perm[0], perm[1] = perm[1], perm[0]
    pre = [None] * (n + 1)
    for k, x in enumerate(perm):
        prevs = perm[:k]
        if not prevs:
            pre[x] = []
            continue
        min_size = 1 if x == 1 else 0
        chosen = draw(st.lists(st.sampled_from(prevs), unique=True,
                               min_size=min_size, max_size=len(prevs)))
        pre[x] = list(chosen)
    lines = [str(n)]
    for i in range(1, n + 1):
        lines.append(" ".join(str(v) for v in [len(pre[i])] + pre[i]))
    return "\n".join(lines) + "\n"


def validate(inp):
    try:
        n, pre = _parse(inp)
    except Exception:
        return False
    if not (2 <= n <= 2 * 10**5):
        return False
    total = 0
    for i in range(1, n + 1):
        ps = pre[i]
        c = len(ps)
        total += c
        if not (0 <= c < n):
            return False
        if len(set(ps)) != c:
            return False
        if any(not (1 <= p <= n) for p in ps):
            return False
    if total > 2 * 10**5:
        return False
    if len(pre[1]) < 1:
        return False
    # acyclicity (Kahn): book x needs its prerequisites first
    indeg = [0] * (n + 1)
    succ = [[] for _ in range(n + 1)]
    for x in range(1, n + 1):
        indeg[x] = len(pre[x])
        for p in pre[x]:
            succ[p].append(x)
    queue = [x for x in range(1, n + 1) if indeg[x] == 0]
    seen = 0
    while queue:
        u = queue.pop()
        seen += 1
        for v in succ[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                queue.append(v)
    return seen == n


def _closure(n, pre):
    S = set()
    stack = [1]
    while stack:
        u = stack.pop()
        if u in S:
            continue
        S.add(u)
        for p in pre[u]:
            if p not in S:
                stack.append(p)
    return S


def ref(inp):
    n, pre = _parse(inp)
    S = _closure(n, pre)
    todo = set(S) - {1}
    read = set()
    order = []
    while todo:
        cands = [b for b in todo if all((p in read) for p in pre[b])]
        b = min(cands)
        order.append(b)
        read.add(b)
        todo.remove(b)
    return " ".join(str(x) for x in order)


def same(inp, expected, got):
    try:
        n, pre = _parse(inp)
        S = _closure(n, pre)
        need = S - {1}
        toks = got.split()
        vals = [int(x) for x in toks]
